css:
:where(.wtyg-map-site_animal_racing),:where(.wtyg-map-site_animal_racing){margin:0; padding:0; height:100%; background:#2d3436; overflow:hidden;}
:where(.wtyg-map-site_animal_racing) :is([data-wtyg-id="racing-map-wrapper"],#wtyg-noid-racing-map-wrapper){position:fixed; top:0; right:0; bottom:0; left:0;
    width:auto !important; height:auto !important;}
:where(.wtyg-map-site_animal_racing) :is([data-wtyg-id="racing-map-display"],#wtyg-noid-racing-map-display){position:absolute; top:0; right:0; bottom:0; left:0;
    width:auto !important; height:auto !important;}
:where(.wtyg-map-site_animal_racing) .racing-filter-btn:hover{background: rgba(255,255,255,0.15) !important;
    border-color: #d4a574 !important;
    transform: translateY(-2px);}
:where(.wtyg-map-site_animal_racing) .racing-filter-btn.active{background: #d4a574 !important;
    border-color: #d4a574 !important;
    color: #2d3436 !important;
    font-weight: 500;}
:where(.wtyg-map-site_animal_racing) .leaflet-popup-content-wrapper{background: rgba(45,52,54,0.98) !important;
    border: 1px solid rgba(255,255,255,0.15);
    border-radius: 1rem;
    box-shadow: 0 20px 60px rgba(0,0,0,0.4);}
:where(.wtyg-map-site_animal_racing) .leaflet-popup-content{margin: 0 !important;
    min-width: 250px;
    font-family: 'Work Sans', sans-serif;}
:where(.wtyg-map-site_animal_racing) .racing-popup-content{padding: 1.25rem;}
:where(.wtyg-map-site_animal_racing) .racing-popup-category{display: inline-block;
    background: #d4a574;
    color: #2d3436;
    padding: 0.3rem 0.8rem;
    border-radius: 1rem;
    font-size: 0.65rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 0.8rem;}
:where(.wtyg-map-site_animal_racing) .racing-popup-name{font-family: 'Cormorant Garamond', serif;
    font-size: 1.3rem;
    font-weight: 600;
    color: #f5f5f0;
    margin-bottom: 0.5rem;
    line-height: 1.3;}
:where(.wtyg-map-site_animal_racing) .racing-popup-address{color: #d4a574;
    font-size: 0.85rem;
    line-height: 1.5;
    margin-bottom: 0.4rem;}
:where(.wtyg-map-site_animal_racing) .racing-popup-country{color: rgba(255,255,255,0.6);
    font-size: 0.8rem;
    font-weight: 300;}
:where(.wtyg-map-site_animal_racing) .leaflet-popup-tip{background: rgba(45,52,54,0.98) !important;}
:where(.wtyg-map-site_animal_racing) .racing-marker-horseracing div{background-color: #e74c3c;}
:where(.wtyg-map-site_animal_racing) .racing-marker-equestrian div{background-color: #9b59b6;}
:where(.wtyg-map-site_animal_racing) .racing-marker-dogracing div{background-color: #3498db;}
:where(.wtyg-map-site_animal_racing) .racing-marker-camelracing div{background-color: #f39c12;}
:where(.wtyg-map-site_animal_racing) .racing-marker-rodeo div{background-color: #e67e22;}
:where(.wtyg-map-site_animal_racing) .racing-marker-bullfighting div{background-color: #c0392b;}
:where(.wtyg-map-site_animal_racing) .racing-marker-polo div{background-color: #16a085;}
:where(.wtyg-map-site_animal_racing) .racing-marker-other div{background-color: #95a5a6;}
